-- Visual preferences only. Native engines, callbacks, item colors and game UI are untouched.
local root=g_ui.getRootWidget()
local previous=root._sabuezoHelperAppearance
if previous and previous.dispose then previous.dispose() end
local A={entries=setmetatable({}, {__mode="k"}),sources={},sourceOrder={},disposed=false}
HelperAppearance=A
root._sabuezoHelperAppearance=A
local keys={"window","panel","button","input","text","accent","border","active"}
local labels={window="Fondo",panel="Paneles",button="Botones",input="Campos",text="Texto",accent="Acento",border="Bordes",active="Activo"}
local dark={window="#172126",panel="#25333D",button="#263640",input="#0F1920",text="#E4EDF3",accent="#50D7D4",border="#58717E",active="#18434A",opacity=100}
local light={window="#E8EFF3",panel="#D9E4EB",button="#C5D6E1",input="#FAFCFD",text="#23343E",accent="#087F8C",border="#829EAD",active="#ADE2E0",opacity=100}
local presets={Oscuro=dark,Claro=light}
local roleMap={
 ['#172126']='window',['#25333d']='panel',['#1b2932']='panel',
 ['#263640']='button',['#212e37']='button',['#304650']='button',
 ['#0f1920']='input',['#e4edf3']='text',['#edf6fa']='text',['#c0cdd6']='text',['#a9bbc6']='text',['#dcffff']='text',['#ffffff']='text',
 ['#50d7d4']='accent',['#58717e']='border',['#3e515e']='border',['#6a8492']='border',['#4d7279']='border',
 ['#18434a']='active',['#1d5359']='active',['#244b53']='active',['#356571']='active',['#1b4650']='active'
}
-- Neutral captions used by the original module forms also follow the text role.
for _,hex in ipairs({'#dfdfdf','#aaaaaa','#c8c8c8','#aeaeae','#edf3f5','#e1e4e3','#e1e8eb','#ced8de',
 '#aebcc3','#a7b5bb','#b5c4cb','#a4b3af','#a6b3bf','#86939e','#dce6ef','#a8bac7','#9dd1ce','#8dd7d1','#a7bdc9'}) do roleMap[hex]='text' end
local colorProps={color=true,['background-color']=true,['border-color']=true,['selection-color']=true,['selection-background-color']=true}
local function clone(value)
 if type(value)~="table" then return value end
 local result={};for k,v in pairs(value) do result[k]=clone(v) end;return result
end
-- This client can fail in C++ on property lookup of an old widget reference.
-- Callers below receive freshly constructed controls or children of live surfaces.
local function valid(w) return type(w)=="table" or type(w)=="userdata" end
local function normalize(value)
 if type(value)~="string" then return nil end
 value=value:gsub("^%s+",""):gsub("%s+$","")
 if value:match("^#%x%x%x%x%x%x$") then return value:upper() end
end
function A.palette(value)
 if type(value)~="table" then return nil end
 local out={}
 for _,key in ipairs(keys) do out[key]=normalize(value[key]);if not out[key] then return nil end end
 local opacity=tonumber(value.opacity)
 if not opacity or opacity~=opacity then return nil end
 out.opacity=math.max(20,math.min(100,math.floor(opacity+0.5)))
 return out
end
local function sameColors(a,b)
 for _,key in ipairs(keys) do if a[key]~=b[key] then return false end end
 return true
end
local function rgb(value) return tonumber(value:sub(2,3),16),tonumber(value:sub(4,5),16),tonumber(value:sub(6,7),16) end
function A.color(value,palette)
 if type(value)~="string" then return value end
 local hex=value:sub(1,7):lower();local role=roleMap[hex]
 if not role or not value:match("^#%x%x%x%x%x%x%x?%x?$") then return value end
 palette=palette or A.current
 local r,g,b=rgb(hex);local dr,dg,db=rgb(dark[role]);local nr,ng,nb=rgb(palette[role])
 local function channel(v) return math.max(0,math.min(255,v)) end
 return string.format("#%02X%02X%02X",channel(r+nr-dr),channel(g+ng-dg),channel(b+nb-db))..value:sub(8)
end
-- Recolor only OTUI color properties. Never alter callback bodies or Lua strings.
function A.transform(source,path)
 local lines,skip,style={},nil,nil
 local folder=path and path:match("^(.*)/[^/]+$")
 for line in (source.."\n"):gmatch("([^\n]*)\n") do
  local indent=#(line:match("^(%s*)") or "");local t=line:match("^%s*(.-)%s*$")
  if skip and t~="" and indent<=skip then skip=nil end
  if not skip then
   if RinoSkin and RinoSkin.transformLine then line=RinoSkin.transformLine(line,path);t=line:match('^%s*(.-)%s*$') end
   if t:sub(1,1)=="@" then skip=indent
   else
    if indent==0 then style=t:match("^(%w+)%s*<") end
    local space,key,value=line:match("^(%s*)([%w%-]+):%s*(.-)%s*$")
    if key then
     if colorProps[key] or key=="background" then line=space..key..": "..A.color(value)
     elseif key=="image-source" and folder and value~="" and value:sub(1,1)~="/" then line=space..key..": "..folder.."/"..value end
     if not sameColors(A.current,dark) and key=="image-source" and (style=="HelperFavorite" or style=="HelperFlatButton") then
      line=space.."image-source:\n"..space.."background-color: "..A.current.button
     end
    end
   end
  end
  lines[#lines+1]=line
 end
 return table.concat(lines,"\n"):gsub("\n$","")
end
local function sourceHash(source)
 source=source:gsub("\r",""):gsub("^%s+",""):gsub("%s+$","")
 local hash=0;for i=1,#source do hash=(hash*31+source:byte(i))%2147483647 end;return hash
end
local fixedIds={previewOn=true,previewOff=true,onColorPreview=true,offColorPreview=true,
 onGreen=true,onLime=true,onCyan=true,onYellow=true,offRed=true,offWhite=true,offOrange=true,offYellow=true,offCyan=true}
local setterProps={setColor="color",setBackgroundColor="background-color",setBorderColor="border-color"}
local function paint(w,entry)
 if not valid(w) or entry.fixed or w.helperAppearanceFixed then return end
 local props={}
 for k,v in pairs(entry.descriptor.props or {}) do props[k]=A.color(v) end
 for state,values in pairs(entry.descriptor.states or {}) do
  props[state]={};for k,v in pairs(values) do props[state][k]=A.color(v) end
 end
 for k,v in pairs(entry.manual) do props[k]=A.color(v) end
 local style=entry.descriptor.style
 if style=="HelperFavorite" then
  props['image-source']=sameColors(A.current,dark) and A.prefix.."vBot/botserver_assets/card.png" or ""
  props['background-color']=sameColors(A.current,dark) and "#00000000" or A.current.button
 elseif style=="HelperFlatButton" then
  for _,state in ipairs({'$hover !disabled','$pressed'}) do
   props[state]=props[state] or {}
   props[state]['image-source']=sameColors(A.current,dark) and A.prefix.."vBot/botserver_assets/"..(state=='$pressed' and 'row-selected.png' or 'row-hover.png') or ""
   props[state]['background-color']=sameColors(A.current,dark) and "#00000000" or A.current.active
  end
 end
 local hasProperties=false;for _ in pairs(props) do hasProperties=true;break end
 if hasProperties and type(w.mergeStyle)=="function" then w:mergeStyle(props) end
 if RinoSkin and RinoSkin.paint then RinoSkin.paint(w,entry) end
end
local function setWindowOpacity(w)
 local value=w:getParent()==root and A.current.opacity/100 or 1
 -- Window's inherited base/drag states must keep the chosen value when focus,
 -- hover or dragging updates its style. A one-shot setter is overwritten then.
 if type(w.mergeStyle)=="function" then w:mergeStyle({opacity=value,['$dragging']={opacity=value}}) end
 w:setOpacity(value)
end
local function widgetEntry(w)
 -- Lua fields belong to the native object, unlike userdata/table key identity.
 -- Called only for fresh controls or widgets found in currently live trees.
 local entry=w._helperAppearanceEntry
 if type(entry)=="table" and entry.owner==A then return entry end
end
local function trackNode(w,descriptor,fixed)
 if not valid(w) or not descriptor then return end
 fixed=fixed or fixedIds[descriptor.id] or (descriptor.id and (descriptor.id:match('Swatch$') or descriptor.id:match('^quick%d+$'))) or false
 local entry=widgetEntry(w)
 if not entry then
  entry={owner=A,descriptor=descriptor,manual={},fixed=fixed,setters={}}
  w._helperAppearanceEntry=entry;A.entries[w]=entry
  for name,prop in pairs(setterProps) do
   local original=w[name]
   if type(original)=="function" and not fixed then
    local wrapper=function(self,value,...)
     entry.manual[prop]=value
     return original(self,(A.disposed or self.helperAppearanceFixed) and value or A.color(value),...)
    end
    entry.setters[name]={original=original,wrapper=wrapper};w[name]=wrapper
   end
  end
 end
 paint(w,entry)
 if descriptor.window and type(w.setOpacity)=="function" then setWindowOpacity(w) end
 local children=w:getChildren();local descriptions=descriptor.children or {}
 for i,childDesc in ipairs(descriptions) do
  local child
  if childDesc.id then
   for _,candidate in ipairs(children) do if candidate:getId()==childDesc.id then child=candidate;break end end
  else child=children[#children-#descriptions+i] end
  if child then trackNode(child,childDesc,fixed) end
 end
end
function A.track(w,style,inline)
 if A.disposed or A.legacy or not A.metadata then return end
 local descriptor=inline and A.metadata.inline[sourceHash(inline)] or A.metadata.styles[style]
 if not descriptor and HelperTheme and HelperTheme.types[style] then descriptor=A.metadata.styles[HelperTheme.types[style]] end
 trackNode(w,descriptor,false)
end
-- Enumerate live root children, then visit ONLY Helper-owned trees. Native
-- equality identifies new userdata references to the same object; table keys do not.
-- Do not iterate the widget cache, inspect native styles or walk the game tree.
function A.visitOwned(visitor,rootsOnly)
 local H=A.owner
 local wanted={}
 if H and not H.disposed then
  if H.window then wanted[#wanted+1]=H.window end
  if H.icon then wanted[#wanted+1]=H.icon end
  for _,panel in ipairs(H.floatingPanels or {}) do if panel.widget then wanted[#wanted+1]=panel.widget end end
 end
 if A.editor then wanted[#wanted+1]=A.editor end
 local function visit(w)
  local entry=widgetEntry(w)
  if entry then visitor(w,entry) end
  if not rootsOnly then for _,child in ipairs(w:getChildren()) do visit(child) end end
 end
 for _,w in ipairs(root:getChildren()) do
  for _,surface in ipairs(wanted) do if w==surface then visit(w);break end end
 end
end
function A.refreshOpacity(widget)
 if A.disposed or A.legacy then return end
 local function refresh(w,entry)
  if entry.descriptor.window and type(w.setOpacity)=="function" then
   setWindowOpacity(w)
  end
 end
 if widget then
  -- Supplied only immediately after construction/mounting by Helper.
  local entry=widgetEntry(widget);if entry then refresh(widget,entry) end
 else A.visitOwned(refresh,true) end
end
local function importSource(path,source)
 return g_ui.importStyleFromString(A.transform(source,path))
end
function A.apply(value)
 local palette=A.palette(value);if not palette then return false,"Paleta invalida." end
 if A.disposed then return false,"El bot ya se ha cerrado." end
 local before=A.current;local colorsChanged=not sameColors(before,palette)
 A.current=palette
 local ok,err=pcall(function()
  if colorsChanged then
   for _,path in ipairs(A.sourceOrder) do importSource(path,A.sources[path]) end
   A.visitOwned(paint)
  end
  A.refreshOpacity()
 end)
 if not ok then
  A.current=before
  pcall(function()
   for _,path in ipairs(A.sourceOrder) do importSource(path,A.sources[path]) end
   A.visitOwned(paint)
   A.refreshOpacity()
  end)
  return false,"No se pudo aplicar la paleta: "..tostring(err)
 end
 return true
end
local function persist(value)
 local profiles=A.profileManager
 if not profiles or not profiles.valid() or type(profiles.saveAppearance)~="function" then
  return false,"No se pudo guardar: el administrador de perfiles no esta disponible. Recarga el bot."
 end
 local ok,message=profiles.saveAppearance(value)
 if not ok then return false,message end
 A.settings=clone(value);return true
end
local function paletteNamed(name) return presets[name] or A.palette(A.settings.saved[name]) end
function A.savePalette(name,value,remember)
 name=tostring(name or ""):gsub("^%s+",""):gsub("%s+$","")
 if name=="" or #name>48 or name:find("%c") then return false,"Escribe un nombre de hasta 48 caracteres." end
 if name:lower()=="oscuro" or name:lower()=="claro" then return false,"Oscuro y Claro son originales. Usa otro nombre." end
 local palette=A.palette(value);if not palette then return false,"Revisa los colores: formato #RRGGBB." end
 for other in pairs(A.settings.saved) do
  if other~=name and other:lower()==name:lower() then return false,"Ya existe una paleta con ese nombre." end
 end
 local settings=clone(A.settings);settings.saved[name]=palette;settings.selected=name;settings.remember=remember==true
 local before=clone(A.current);local ok,err=A.apply(palette);if not ok then return false,err end
 ok,err=persist(settings);if not ok then A.apply(before);return false,err end
 A.applied=clone(palette);A.appliedName=name;return true
end
function A.commit(value,name,remember)
 value=A.palette(value);if not value then return false,"Paleta invalida." end
 local settings=clone(A.settings);settings.remember=remember==true
 local named=paletteNamed(name)
 local clean=named and sameColors(named,value) and named.opacity==value.opacity
 if clean then settings.selected=name end
 local before=clone(A.current);local ok,err=A.apply(value);if not ok then return false,err end
 ok,err=persist(settings);if not ok then A.apply(before);return false,err end
 A.applied=clone(A.current);A.appliedName=clean and name or nil
 return true,clean and "Paleta aplicada." or "Cambios aplicados. Guarda con un nombre para recordarlos."
end
function A.deletePalette(name)
 if presets[name] or not A.settings.saved[name] then return false,"Selecciona una paleta propia." end
 local settings=clone(A.settings);settings.saved[name]=nil
 if settings.selected==name then settings.selected="Oscuro" end
 local active=A.appliedName==name
 local before=clone(A.current)
 if active then local ok,err=A.apply(dark);if not ok then return false,err end end
 local ok,err=persist(settings);if not ok then if active then A.apply(before) end;return false,err end
 if active then A.applied=clone(dark);A.appliedName="Oscuro" end
 return true
end
function A.cancel()
 if A.disposed then return end
 local ok,message=A.apply(A.applied)
 if not ok then if valid(A.editor) then A.editor.feedback:setText(message) end;return false end
 if valid(A.editor) then A.editor:hide() end
end
function A.open(H)
 if A.disposed or A.legacy then return end
 A.owner=H
 if valid(A.editor) then A.editor:show();A.editor:raise();return end
 local w=H.originals.createWindow("HelperAppearanceWindow",root)
 A.editor=w;w.botWidget=true;A.track(w,"HelperAppearanceWindow")
 local bounds=root:getRect();local size=w:getSize();local origin=H.window:getPosition()
 w:breakAnchors();w:setPosition({x=math.max(bounds.x,math.min(origin.x+24,bounds.x+bounds.width-size.width)),y=math.max(bounds.y,math.min(origin.y+30,bounds.y+bounds.height-size.height))})
 local draft,selected=clone(A.applied),A.appliedName or A.settings.selected
 local editing,activeKey=false,"window"
 local function feedback(message) w.feedback:setText(message or "") end
 local function swatch(button,color)
  button:setBackgroundColor(color)
  if type(button.mergeStyle)=="function" then button:mergeStyle({['background-color']=color,['$hover !disabled']={['background-color']=color},['$pressed']={['background-color']=color}}) end
 end
 local function preview()
  if editing then return end
  local ok,message=A.apply(draft);if not ok then feedback(message) end
 end
 local function options()
  editing=true;w.palette:clearOptions();w.palette:addOption("Oscuro");w.palette:addOption("Claro")
  local names={};for name in pairs(A.settings.saved) do names[#names+1]=name end;table.sort(names,function(a,b)return a:lower()<b:lower()end)
  for _,name in ipairs(names) do w.palette:addOption(name) end
  w.palette:setCurrentOption(selected or "Oscuro");editing=false
 end
 local function render()
  editing=true
  for _,key in ipairs(keys) do w[key.."Hex"]:setText(draft[key]);swatch(w[key.."Swatch"],draft[key]) end
  w.opacity:setValue(draft.opacity);w.opacityValue:setText(draft.opacity.."%")
  w.deletePalette:setEnabled(A.settings.saved[selected]~=nil)
  w.quickTitle:setText("Color rapido: "..labels[activeKey]);editing=false
 end
 w.palette.onOptionChange=function()
  if editing then return end
  local option=w.palette:getCurrentOption();if not option then return end
  local palette=paletteNamed(option.text);if not palette then return end
  selected=option.text;draft=clone(palette);w.paletteName:setText(presets[selected] and "" or selected)
  render();preview();feedback("Vista previa. Aplicar confirma; Guardar conserva una paleta propia.")
 end
 for _,key in ipairs(keys) do
  local field=w[key.."Hex"]
  field:setTooltip(labels[key]..": escribe #RRGGBB o elige un color rapido. No cambia los colores de las acciones ni de tus iconos.")
  field.onFocusChange=function(_,focused) if focused then activeKey=key;w.quickTitle:setText("Color rapido: "..labels[key]) end end
  field.onTextChange=function(widget)
   if editing then return end
   local color=normalize(widget:getText());if not color then feedback("Color incompleto: usa #RRGGBB.");return end
   draft[key]=color;swatch(w[key.."Swatch"],color);preview();feedback("Cambios en vista previa. Guarda una paleta para conservarlos.")
  end
  w[key.."Swatch"].onClick=function() activeKey=key;field:focus();w.quickTitle:setText("Color rapido: "..labels[key]) end
 end
 local quick={"#172126","#E8EFF3","#FFFFFF","#50D7D4","#087F8C","#F0B55B","#B49BEE",
  "#101820","#37474F","#607D8B","#9EAFBA","#D9E4EB",
  "#F87171","#EF4444","#F97316","#FACC15","#A3E635","#22C55E",
  "#10B981","#38BDF8","#3B82F6","#8B5CF6","#D946EF","#F472B6"}
 for i,color in ipairs(quick) do
  local button=w["quick"..i];button.helperAppearanceFixed=true
  swatch(button,color);button:setTooltip(color.." | Aplica al campo seleccionado")
  button.onClick=function() draft[activeKey]=color;render();preview();feedback("Color cambiado. Guarda una paleta para conservarlo.") end
 end
 w.opacity:setMinimum(20);w.opacity:setMaximum(100);w.opacity:setStep(1)
 w.opacity:setTooltip("100% = solido. 20% = transparente. Solo las ventanas del bot; los iconos mantienen su ajuste propio.")
 w.opacity.onValueChange=function(widget)
  if editing then return end
  draft.opacity=math.max(20,math.min(100,math.floor(tonumber(widget:getValue()) or draft.opacity)))
  w.opacityValue:setText(draft.opacity.."%");preview()
 end
 w.remember:setTooltip("Al recargar usa la paleta guardada seleccionada. Si lo desmarcas, inicia en Oscuro.")
 local function validateFields()
  for _,key in ipairs(keys) do if not normalize(w[key.."Hex"]:getText()) then feedback("Revisa el color de "..labels[key]..".");return false end end
  return true
 end
 w.savePalette.onClick=function()
  if not validateFields() then return end
  local ok,message=A.savePalette(w.paletteName:getText(),draft,w.remember:isChecked())
  if not ok then feedback(message);return end
  selected=A.appliedName;options();render();feedback("Paleta guardada: "..selected)
 end
 w.deletePalette.onClick=function()
  local ok,message=A.deletePalette(selected);if not ok then feedback(message);return end
  selected="Oscuro";draft=clone(dark);options();render();preview();feedback("Paleta eliminada. Aplicar confirma Oscuro.")
 end
 w.reset.onClick=function() selected="Oscuro";draft=clone(dark);options();render();preview();feedback("Oscuro original en vista previa.") end
 w.apply.onClick=function()
  if not validateFields() then return end
  local ok,message=A.commit(draft,selected,w.remember:isChecked());feedback(message);if ok and A.appliedName then w:hide() end
 end
 w.cancel.onClick=A.cancel;w.closeButton.onClick=A.cancel;w.onClose=function() A.cancel();return true end;w.onEscape=w.onClose
 w.onDestroy=function() A.editor=nil end
 w.remember:setChecked(A.settings.remember)
 w.paletteName:setText(A.settings.saved[selected] and selected or "")
 options();render();feedback("Cambios en vivo. Guardar conserva la paleta; Cancelar revierte la vista previa.");w:show();w:raise()
 -- Reopen rebuilds the draft from the last applied palette.
 local nativeHide=w.hide
 w.hide=function(self) nativeHide(self);self:destroy() end
end
function A.dispose()
 if A.disposed then return end
 A.disposed=true
 -- Surviving setter closures become plain passthroughs when disposed. Do not
 -- inspect cached widgets during reload: game_bot may already have removed them.
 A.entries=setmetatable({}, {__mode="k"});A.owner=nil
 if g_ui.importStyle==A.importWrapper then g_ui.importStyle=A.originalImport end
 -- Destroy only a currently attached owned editor; never dereference the cache.
 for _,w in ipairs(root:getChildren()) do if w==A.editor then w:destroy();break end end
 A.editor=nil
 if root._sabuezoHelperAppearance==A then root._sabuezoHelperAppearance=nil end
end
function A.install()
 storage.helperUI=type(storage.helperUI)=="table" and storage.helperUI or {}
 local stored=type(storage.helperUI.appearance)=="table" and storage.helperUI.appearance or {}
 A.profileManager=HelperProfiles
 A.settings={version=1,rpgVersion=stored.rpgVersion,saved={},selected=type(stored.selected)=="string" and stored.selected or "Oscuro",remember=stored.remember~=false}
 for name,value in pairs(type(stored.saved)=="table" and stored.saved or {}) do
  if type(name)=="string" and not presets[name] then local palette=A.palette(value);if palette then A.settings.saved[name]=palette end end
 end
 A.legacy=storage.helperUI.legacy==true
 local selected=A.settings.remember and paletteNamed(A.settings.selected) and A.settings.selected or "Oscuro"
 A.current=clone(paletteNamed(selected));A.applied=clone(A.current);A.appliedName=selected
 A.prefix="/bot/"..modules.game_bot.contentsPanel.config:getCurrentOption().text.."/"
 if A.legacy then A.current=clone(dark);A.applied=clone(dark);return end
 A.originalImport=g_ui.importStyle
 A.importWrapper=function(path,...)
  if type(path)~="string" or path:sub(1,#A.prefix)~=A.prefix or not g_resources or not g_resources.readFileContents then return A.originalImport(path,...) end
  if not g_resources.fileExists(path) then
    warn('Apariencia: archivo de estilo faltante: '..path)
    return false
  end
  local ok,source=pcall(g_resources.readFileContents,path)
  if not ok or type(source)~="string" then return A.originalImport(path,...) end
  if not A.sources[path] then A.sourceOrder[#A.sourceOrder+1]=path end;A.sources[path]=source
  if sameColors(A.current,dark) and not (RinoSkin and RinoSkin.prefix) then return A.originalImport(path,...) end
  return importSource(path,source)
 end
 g_ui.importStyle=A.importWrapper
end

-- Generated offline; appearance colors only; no callbacks/images.
-- Each descriptor is kept as source text and built the first time its style is asked for
-- (lookups are always by name): parsing and building ~24,000 nested tables on every
-- reload cost 0.2-0.5 s in the client. Assigning a style (RinoSkin does) works as before.
