local compile=loadstring or load
local function lazy(sources)
 return setmetatable({},{__index=function(t,key)
  local text=sources[key]
  if text==nil then return nil end
  local chunk=compile(text,"=appearance")
  local value=chunk and chunk()
  t[key]=value -- the table has no __newindex, so this stores it (rawset is not available in the bot)
  return value
 end})
end
A.metadata={styles=lazy(rawStyles),inline=lazy(rawInline)}

A.install()
